input.sparql:
SELECT ?zone ?zoneName ?sensor WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasSubComponent ?sensor .
  ?sensor a brick:AirTemperatureSensor .
  ?zone rdfs:label ?zoneName .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?zone ?zoneLabel ?sensor ?series WHERE {
  ?sensor brick:isPointOf ?zone .
  ?zone a brick:Zone .
  ?sensor a brick:Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?series . }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p WHERE {
  ?s a ?p .
  FILTER (str(?p) CONTAINS "Temperature")
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?s ?t WHERE {
  ?s a brick:Air_Temperature_Sensor .
  ?s a ?t .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?zone ?ext ?series WHERE {
  ?sensor brick:isPointOf ?zone .
  ?sensor a brick:Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?series . }
  OPTIONAL { ?sensor ref:hasExternalReference ?ext . }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT DISTINCT ?t WHERE {
  ?sensor a ?t .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?zone ?ext ?series WHERE {
  ?sensor brick:isPointOf ?zone .
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasExternalReference ?ext . }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?series . }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?z WHERE {
  ?z a brick:HVAC_Zone .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?ext ?tid WHERE {
  ?sensor brick:isPointOf ?zone .
  ?zone a brick:HVAC_Zone .
  ?sensor a brick:Air_Temperature_Sensor .
  OPTIONAL { ?sensor ref:hasExternalReference ?ext .
    ?ext ref:hasTimeseriesId ?tid .
  }
}

